import{_ as a,H as n,f as i,i as p}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"01-Kotlin基础语法：正式开启学习之旅","description":"","frontmatter":{},"headers":[{"level":2,"title":"开发环境","slug":"开发环境","link":"#开发环境","children":[]},{"level":2,"title":"变量","slug":"变量","link":"#变量","children":[]},{"level":2,"title":"基础类型","slug":"基础类型","link":"#基础类型","children":[{"level":3,"title":"一切都是对象","slug":"一切都是对象","link":"#一切都是对象","children":[]},{"level":3,"title":"空安全","slug":"空安全","link":"#空安全","children":[]},{"level":3,"title":"数字类型","slug":"数字类型","link":"#数字类型","children":[]},{"level":3,"title":"布尔类型","slug":"布尔类型","link":"#布尔类型","children":[]},{"level":3,"title":"字符：Char","slug":"字符-char","link":"#字符-char","children":[]},{"level":3,"title":"字符串：String","slug":"字符串-string","link":"#字符串-string","children":[]},{"level":3,"title":"数组","slug":"数组","link":"#数组","children":[]}]},{"level":2,"title":"函数声明","slug":"函数声明","link":"#函数声明","children":[{"level":3,"title":"函数调用","slug":"函数调用","link":"#函数调用","children":[]}]},{"level":2,"title":"流程控制","slug":"流程控制","link":"#流程控制","children":[{"level":3,"title":"if","slug":"if","link":"#if","children":[]},{"level":3,"title":"when","slug":"when","link":"#when","children":[]},{"level":3,"title":"循环迭代：while 与 for","slug":"循环迭代-while-与-for","link":"#循环迭代-while-与-for","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"朱涛·Kotlin编程第一课/01-Kotlin基础语法：正式开启学习之旅.md","filePath":"朱涛·Kotlin编程第一课/01-Kotlin基础语法：正式开启学习之旅.md","lastUpdated":1795558358000}'),l={name:"朱涛·Kotlin编程第一课/01-Kotlin基础语法：正式开启学习之旅.md"};function e(t,s,h,o,c,d){return n(),i("div",null,[...s[0]||(s[0]=[p(`<h1 id="_01-kotlin基础语法-正式开启学习之旅" tabindex="-1">01-Kotlin基础语法：正式开启学习之旅 <a class="header-anchor" href="#_01-kotlin基础语法-正式开启学习之旅" aria-label="Permalink to &quot;01-Kotlin基础语法：正式开启学习之旅&quot;">​</a></h1><p>你好，我是朱涛。从今天开始，我们就正式踏上 Kotlin 语言学习与实践的旅途了。这节课，我想先带你来学习下 Kotlin 的基础语法，包括变量、基础类型、函数和流程控制。这些基础语法是程序最基本的元素。</p><p>不过，如果你有使用 Java 的经验，可能会觉得今天的内容有点多余，毕竟 Kotlin 和 Java 的基础语法是比较相似的，它们都是基于 JVM 的语言。但其实不然，Kotlin 作为一门新的语言，它包含了许多新的特性，由此也决定着 Kotlin 的代码风格。如果你不够了解 Kotlin 的这些新特性，你会发现自己只是换了种方式在写 Java 而已。</p><p>并且，在具备 Java 语言的知识基础上，这节课的内容也可以帮你快速将已有的经验迁移过来。这样的话，针对相似的语法，你可以直接建立 Kotlin 与 Java 的对应关系，进而加深理解。当然，即使你没有其他编程经验也没关系，从头学即可，Kotlin 的语法足够简洁，也非常适合作为第一门计算机语言来学习。</p><p>在课程中，我会用最通俗易懂的语言，来给你解释 Kotlin 的基础知识，并且会结合一些 Java和 Kotlin 的代码案例，来帮助你直观地体会两种语言的异同点。而针对新的语法，我也会详细解释它存在的意义，以及都填补了 Java 的哪些短板，让你可以对 Kotlin 新语法的使用场景做到心中基本有数。</p><h2 id="开发环境" tabindex="-1">开发环境 <a class="header-anchor" href="#开发环境" aria-label="Permalink to &quot;开发环境&quot;">​</a></h2><p>在正式开始学习基础语法之前，我们还需要配置一下 Kotlin 语言的环境，因为直接从代码开始学能给我们带来最直观的体验。</p><p>那么要运行 Kotlin 代码，最快的方式，就是使用 Kotlin 官方的PlayGround。通过这个在线工具，我们可以非常方便地运行 Kotlin 代码片段。当然，这种方式用来临时测试一小段代码是没有问题的，但对于复杂的工程就有些力不从心了。</p><p>另一种方式，也是我个人比较推荐的方式，那就是安装IntelliJ IDEA。它是 Kotlin 官方提供的集成开发工具，也是世界上最好的 IDE 之一，如果你用过 Android Studio，你一定会对它很熟悉，因为 Android Studio 就是由 IntelliJ IDEA 改造的。</p><p>如果你的电脑没有 Java 环境，在安装完最新版的 IntelliJ IDEA 以后，通过“File -&gt; ProjectStructure -&gt; SDKs”，然后点击“加号按钮”就可以选择第三方提供的 OpenJDK 1.8 版本进行下载了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9C%B1%E6%B6%9B%C2%B7Kotlin%E7%BC%96%E7%A8%8B%E7%AC%AC%E4%B8%80%E8%AF%BE/images/01-Kotlin%25E5%259F%25BA%25E7%25A1%2580%25E8%25AF%25AD%25E6%25B3%2595/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9C%B1%E6%B6%9B%C2%B7Kotlin%E7%BC%96%E7%A8%8B%E7%AC%AC%E4%B8%80%E8%AF%BE/images/01-Kotlin%25E5%259F%25BA%25E7%25A1%2580%25E8%25AF%25AD%25E6%25B3%2595/1.png" alt=""></a></p><p>当然，这里我更推荐你可以自己手动从Oracle 官网下载 JDK 1.6、1.7、1.8、11 这几个版本，然后再安装、配置 Java 多版本环境。这在实际工作中也是必备的。</p><p>需要注意的是，IntelliJ IDEA 分为 Ultimate 付费版和 Community 免费版，对于我们的 Kotlin学习来说，免费版完全够用。</p><p>这样，在配置好了开发环境之后，我们就可以试着一边敲代码，一边体会、思考和学习 Kotlin语言中这些最基础的语法知识了。那么下面我们就来看下，在 Kotlin 语言中是如何定义变量的吧。</p><h2 id="变量" tabindex="-1">变量 <a class="header-anchor" href="#变量" aria-label="Permalink to &quot;变量&quot;">​</a></h2><p>在 Java/C 当中，如果我们要声明变量，我们必须要声明它的类型，后面跟着变量的名称和对应的值，然后以分号结尾。就像这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Integer price = 100;</span></span></code></pre></div><p>而 Kotlin 则不一样，我们要使用“val”或者是“var”这样的关键字作为开头，后面跟“变量名称”，接着是“变量类型”和“赋值语句”，最后是分号结尾。就像这样：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/*</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">关键字     变量类型</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">↓          ↓           */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> price</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Int</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/*</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    ↑            ↑</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  变量名        变量值   */</span></span></code></pre></div><p>不过，像 Java 那样每写一行代码就写一个分号，其实也挺麻烦的。所以为了省事，在 Kotlin里面，我们一般会把代码末尾的分号省略，就像这样：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> price</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Int</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span></span></code></pre></div><p>另外，由于 Kotlin 支持类型推导，大部分情况下，我们的变量类型可以省略不写，就像这样：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> price </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 默认推导类型为： Int</span></span></code></pre></div><p>还有一点我们要注意，就是在 Kotlin 当中，我们应该尽可能避免使用 var，尽可能多地去使用val。</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> price </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">price </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 101</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">val i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 编译器报错</span></span></code></pre></div><p>原因其实很简单：</p><ul><li><p>val 声明的变量，我们叫做不可变变量，它的值在初始化以后就无法再次被修改，它相当于Java 里面的 final 变量。</p></li><li><p>var 声明的变量，我们叫做可变变量，它对应 Java 里的普通变量。</p></li></ul><h2 id="基础类型" tabindex="-1">基础类型 <a class="header-anchor" href="#基础类型" aria-label="Permalink to &quot;基础类型&quot;">​</a></h2><p>了解了变量类型如何声明之后，我们再来看下 Kotlin 中的基础类型。</p><p>基础类型，包括我们常见的数字类型、布尔类型、字符类型，以及前面这些类型组成的数组。这些类型是我们经常会遇到的概念，因此我们把它统一归为“基础类型”。</p><h3 id="一切都是对象" tabindex="-1">一切都是对象 <a class="header-anchor" href="#一切都是对象" aria-label="Permalink to &quot;一切都是对象&quot;">​</a></h3><p>在 Java 里面，基础类型分为原始类型（Primitive Types）和包装类型（Wrapper Type）。比如，整型会有对应的 int 和 Integer，前者是原始类型，后者是包装类型。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int i = 0; // 原始类型</span></span>
<span class="line"><span>Integer j = 1; // 包装类型</span></span></code></pre></div><p>Java 之所以要这样做，是因为原始类型的开销小、性能高，但它不是对象，无法很好地融入到面向对象的系统中。而包装类型的开销大、性能相对较差，但它是对象，可以很好地发挥面向对象的特性。在 JDK 源码当中，我们可以看到 Integer 作为包装类型，它是有成员变量以及成员方法的，这就是它作为对象的优势。</p><p>然而，在 Kotlin 语言体系当中，是没有原始类型这个概念的。这也就意味着，在 Kotlin 里，一切都是对象。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9C%B1%E6%B6%9B%C2%B7Kotlin%E7%BC%96%E7%A8%8B%E7%AC%AC%E4%B8%80%E8%AF%BE/images/01-Kotlin%25E5%259F%25BA%25E7%25A1%2580%25E8%25AF%25AD%25E6%25B3%2595/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9C%B1%E6%B6%9B%C2%B7Kotlin%E7%BC%96%E7%A8%8B%E7%AC%AC%E4%B8%80%E8%AF%BE/images/01-Kotlin%25E5%259F%25BA%25E7%25A1%2580%25E8%25AF%25AD%25E6%25B3%2595/2.png" alt=""></a></p><p>实际上，从某种程度上讲，Java 的类型系统并不是完全面向对象的，因为它存在原始类型，而原始类型并不属于对象。而 Kotlin 则不一样，它从语言设计的层面上就规避了这个问题，类型系统则是完全面向对象的。</p><p>我们看一段代码，来更直观地感受 Kotlin 的独特之处：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val i: Double = 1.toDouble()</span></span></code></pre></div><p>可以发现，由于在 Kotlin 中，整型数字“1”被看作是对象了，所以我们可以调用它的成员方法toDouble()，而这样的代码在 Java 中是无法实现的。</p><h3 id="空安全" tabindex="-1">空安全 <a class="header-anchor" href="#空安全" aria-label="Permalink to &quot;空安全&quot;">​</a></h3><p>既然 Kotlin 中的一切都是对象，那么对象就有可能为空。也许你会想到写这样的代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val i: Double = null // 编译器报错</span></span></code></pre></div><p>可事实上，以上的代码并不能通过 Kotlin 编译。这是因为 Kotlin 强制要求开发者在定义变量的时候，指定这个变量是否可能为 null。对于可能为 null 的变量，我们需要在声明的时候，在变量类型后面加一个问号“?”：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val i: Double = null // 编译器报错</span></span>
<span class="line"><span>val j: Double? = null // 编译通过</span></span></code></pre></div><p>并且由于 Kotlin 对可能为空的变量类型做了强制区分，这就意味着，“可能为空的变量”无法直接赋值给“不可为空的变量”，当然，反向赋值是没有问题的。</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Double</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> j</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Double</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> j  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 编译器报错</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">j </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 编译通过</span></span></code></pre></div><p>Kotlin 这么设计的原因也很简单，如果我们将“可能为空的变量”直接赋值给了“不可为空的变量”，这会跟它自身的定义产生冲突。而如果我们实在有这样的需求，也不难实现，只要做个判断即可：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Double</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">val </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">j</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: Double</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (j </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> j  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 编译通过</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>好，在了解了 Kotlin 和 Java 这两种语言的主要区别后，下面就让我们来全面认识下 Kotlin 的基础类型。</p><h3 id="数字类型" tabindex="-1">数字类型 <a class="header-anchor" href="#数字类型" aria-label="Permalink to &quot;数字类型&quot;">​</a></h3><p>首先，在数字类型上，Kotlin 和 Java 几乎是一致的，包括它们对数字“字面量”的定义方式。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val int = 1</span></span>
<span class="line"><span>val long = 1234567L</span></span>
<span class="line"><span>val double = 13.14</span></span>
<span class="line"><span>val float = 13.14F</span></span>
<span class="line"><span>val hexadecimal = 0xAF</span></span>
<span class="line"><span>val binary = 0b01010101</span></span></code></pre></div><p>这里我也来给你具体介绍下：</p><ul><li><p>整数默认会被推导为“Int”类型；</p></li><li><p>Long 类型，我们则需要使用“L”后缀；</p></li><li><p>小数默认会被推导为“Double”，我们不需要使用“D”后缀；</p></li><li><p>Float 类型，我们需要使用“F”后缀；</p></li><li><p>使用“0x”，来代表十六进制字面量；</p></li><li><p>使用“0b”，来代表二进制字面量。</p></li></ul><p>但是，对于数字类型的转换，Kotlin 与 Java 的转换行为是不一样的。Java 可以隐式转换数字类型，而 Kotlin 更推崇显式转换。</p><p>举个简单的例子，在 Java 和 C 当中，我们经常直接把 int 类型赋值给 long 类型，编译器会自动为我们做类型转换，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int i = 100;</span></span>
<span class="line"><span>long j = i;</span></span></code></pre></div><p>这段代码按照 Java 的编程思维方式来看，的确好像是 OK 的。但是你要注意，虽然 Java 编译器不会报错，可它仍然可能会带来问题，因为它们本质上不是一个类型，int、long、float、double 这些类型之间的互相转换是存在精度问题的。尤其是当这样的代码掺杂在复杂的逻辑中时，在碰到一些边界条件的情况下，即使出现了 Bug 也不容易排查出来。</p><p>所以，同样的代码，在 Kotlin 当中是行不通的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val i = 100</span></span>
<span class="line"><span>val j: Long = i // 编译器报错</span></span></code></pre></div><p>在 Kotlin 里，这样的隐式转换被抛弃了。正确的做法应该是显式调用 Int 类型的 toLong() 函数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val i = 100</span></span>
<span class="line"><span>val j: Long = i.toLong() // 编译通过</span></span></code></pre></div><p>其实，如果我们仔细翻看 Kotlin 的源代码，会发现更多类似的函数，比如 toByte()、toShort()、toInt()、toLong()、toFloat()、toDouble()、toChar() 等等。Kotlin 这样设计的优势也是显而易见的，我们代码的可读性更强了，将来也更容易维护了。</p><h3 id="布尔类型" tabindex="-1">布尔类型 <a class="header-anchor" href="#布尔类型" aria-label="Permalink to &quot;布尔类型&quot;">​</a></h3><p>然后我们再来了解下 Kotlin 中布尔类型的变量，它只有两种值，分别是 true和false。布尔类型支持一些逻辑操作，比如说：</p><ul><li><p>“&amp;”代表“与运算”；</p></li><li><p>“|”代表“或运算”；</p></li><li><p>“!”代表“非运算”；</p></li><li><p>“&amp;&amp;”和“||”分别代表它们对应的“短路逻辑运算”。</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val i = 1</span></span>
<span class="line"><span>val j = 2</span></span>
<span class="line"><span>val k = 3</span></span>
<span class="line"><span>val isTrue: Boolean = i &lt; j &amp;&amp; j &lt; k</span></span></code></pre></div><h3 id="字符-char" tabindex="-1">字符：Char <a class="header-anchor" href="#字符-char" aria-label="Permalink to &quot;字符：Char&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Char 用于代表单个的字符，比如&#39;A&#39;、&#39;B&#39;、&#39;C&#39;，字符应该用单引号括起来。</span></span>
<span class="line"><span>val c: Char = &#39;A&#39;</span></span></code></pre></div><p>如果你有 Java 或 C 的使用经验，也许会写出这样的代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val c: Char = &#39;A&#39;</span></span>
<span class="line"><span>val i: Int = c // 编译器报错</span></span></code></pre></div><p>这个问题其实跟前面 Java 的数字类型隐式转换的问题类似，所以针对这种情况，我们应该调用对应的函数来做类型转换。这一点我们一定要牢记在心。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val c: Char = &#39;A&#39;</span></span>
<span class="line"><span>val i: Int = c.toInt() // 编译通过</span></span></code></pre></div><h3 id="字符串-string" tabindex="-1">字符串：String <a class="header-anchor" href="#字符串-string" aria-label="Permalink to &quot;字符串：String&quot;">​</a></h3><p>字符串（String），顾名思义，就是一连串的字符。和 Java 一样，Kotlin 中的字符串也是不可变的。在大部分情况下，我们会使用双引号来表示字符串的字面量，这一点跟 Java 也是一样的。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val s = &quot;Hello Kotlin!&quot;</span></span></code></pre></div><p>不过与此同时，Kotlin 还为我们提供了非常简洁的字符串模板：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val name = &quot;Kotlin&quot;</span></span>
<span class="line"><span>print(&quot;Hello $name!&quot;)</span></span>
<span class="line"><span>/*            ↑</span></span>
<span class="line"><span>   直接在字符串中访问变量</span></span>
<span class="line"><span>*/</span></span>
<span class="line"><span>// 输出结果：</span></span>
<span class="line"><span>Hello Kotlin!</span></span></code></pre></div><p>这样的特性，在 Java 当中是没有的，这是 Kotlin 提供的新特性。虽然说这个字符串模板功能，我们用 Java 也同样可以实现，但它远没有 Kotlin 这么简洁。在 Java 当中，我们必须使</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用两个“+”进行拼接，比如说(&quot;Hello&quot; + name + &quot;!&quot;)。这样一来，在字符串格式更复杂</span></span></code></pre></div><p>的情况下，代码就会很臃肿。</p><p>当然，如果我们需要在字符串当中引用更加复杂的变量，则需要使用花括号将变量括起来：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val array = arrayOf(&quot;Java&quot;, &quot;Kotlin&quot;)</span></span>
<span class="line"><span>print(&quot;Hello \${array.get(1)}!&quot;)</span></span>
<span class="line"><span>/*            ↑</span></span>
<span class="line"><span>     复杂的变量，使用\${}</span></span>
<span class="line"><span>*/</span></span>
<span class="line"><span>// 输出结果：</span></span>
<span class="line"><span>Hello Kotlin!</span></span></code></pre></div><p>另外，Kotlin 还新增了一个原始字符串，是用三个引号来表示的。它可以用于存放复杂的多行文本，并且它定义的时候是什么格式，最终打印也会是对应的格式。所以当我们需要复杂文本的时候，就不需要像 Java 那样写一堆的加号和换行符了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val s = &quot;&quot;&quot;</span></span>
<span class="line"><span>      当我们的字符串有复杂的格式时</span></span>
<span class="line"><span>      原始字符串非常的方便</span></span>
<span class="line"><span>      因为它可以做到所见即所得。 &quot;&quot;&quot;</span></span>
<span class="line"><span>print(s)</span></span></code></pre></div><h3 id="数组" tabindex="-1">数组 <a class="header-anchor" href="#数组" aria-label="Permalink to &quot;数组&quot;">​</a></h3><p>最后，我们再来看看 Kotlin 中数组的一些改变。</p><p>在 Kotlin 当中，我们一般会使用 arrayOf() 来创建数组，括号当中可以用于传递数组元素进行初始化，同时，Kotlin 编译器也会根据传入的参数进行类型推导。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val arrayInt = arrayOf(1, 2, 3)</span></span>
<span class="line"><span>val arrayString = arrayOf(&quot;apple&quot;, &quot;pear&quot;)</span></span></code></pre></div><p>比如说，针对这里的 arrayInt，由于我们赋值的时候传入了整数，所以它的类型会被推导为整型数组；对于 arrayString，它的类型会被推导为字符串数组。</p><p>而你应该也知道，在 Java 当中，数组和其他集合的操作是不一样的。举个例子，如果要获取数组的长度，Java 中应该使用“array.length”；但如果是获取 List 的大小，那么 Java 中则应该使用“list.size”。这主要是因为数组不属于 Java 集合。</p><p>不过，Kotlin 在这个问题的处理上并不一样。虽然 Kotlin 的数组仍然不属于集合，但它的一些操作是跟集合统一的。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val array = arrayOf(&quot;apple&quot;, &quot;pear&quot;)</span></span>
<span class="line"><span>println(&quot;Size is \${array.size}&quot;)</span></span>
<span class="line"><span>println(&quot;First element is \${array[0]}&quot;)</span></span>
<span class="line"><span>// 输出结果：</span></span>
<span class="line"><span>Size is 2</span></span>
<span class="line"><span>First element is apple</span></span></code></pre></div><p>就比如说，以上代码中，我们直接使用 array.size 就能拿到数组的长度。</p><h2 id="函数声明" tabindex="-1">函数声明 <a class="header-anchor" href="#函数声明" aria-label="Permalink to &quot;函数声明&quot;">​</a></h2><p>好，了解了 Kotlin 中变量和基础类型的相关概念之后，我们再来看看它的函数是如何定义的。</p><p>在 Kotlin 当中，函数的声明与 Java 不太一样，让我们看一段简单的 Kotlin 代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/*</span></span>
<span class="line"><span>关键字    函数名          参数类型   返回值类型</span></span>
<span class="line"><span>↓        ↓                ↓       ↓      */</span></span>
<span class="line"><span>fun helloFunction(name: String): String {</span></span>
<span class="line"><span>   return &quot;Hello $name !&quot;</span></span>
<span class="line"><span>}/*   ↑</span></span>
<span class="line"><span>  花括号内为：函数体</span></span>
<span class="line"><span>*/</span></span></code></pre></div><p>可以看到，在这段代码中：</p><ul><li><p>使用了 fun 关键字来定义函数；</p></li><li><p>函数名称，使用的是驼峰命名法（大部分情况下）；</p></li><li><p>函数参数，是以 (name: String) 这样的形式传递的，这代表了参数类型为 String 类型；</p></li><li><p>返回值类型，紧跟在参数的后面；</p></li><li><p>最后是花括号内的函数体，它代表了整个函数的逻辑。</p></li></ul><p>另外你可以再注意一个地方，前面代码中的 helloFunction 函数，它的函数体实际上只有一行代码。那么针对这种情况，我们其实就可以省略函数体的花括号，直接使用“=”来连接，将其变成一种类似变量赋值的函数形式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fun helloFunction(name: String): String = &quot;Hello $name !&quot;</span></span></code></pre></div><p>这种写法，我们称之为单一表达式函数。需要注意的是，在这种情况下，表达式当中的“return”是需要去掉的。</p><p>另外，由于 Kotlin 支持类型推导，我们在使用单一表达式形式的时候，返回值的类型也可以省略：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fun helloFunction(name: String) = &quot;Hello $name !&quot;</span></span></code></pre></div><p>看到这里，你一定能体会到 Kotlin 的魅力。它的语法非常得简洁，并且是符合人类的阅读直觉的，我们读这样的代码，就跟读自然语言一样轻松。</p><p>然而，Kotlin 的优势不仅仅体现在函数声明上，在函数调用的地方，它也有很多独到之处。</p><h3 id="函数调用" tabindex="-1">函数调用 <a class="header-anchor" href="#函数调用" aria-label="Permalink to &quot;函数调用&quot;">​</a></h3><p>以我们前面定义的函数为例子，如果我们想要调用它，代码的风格和 Java 基本一致：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>helloFunction(&quot;Kotlin&quot;)</span></span></code></pre></div><p>不过，Kotlin 提供了一些新的特性，那就是命名参数。简单理解，就是它允许我们在调用函数的时候传入“形参的名字”。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>helloFunction(name = &quot;Kotlin&quot;)</span></span></code></pre></div><p>让我们看一个更具体的使用场景：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fun createUser(</span></span>
<span class="line"><span>   name: String,</span></span>
<span class="line"><span>   age: Int,</span></span>
<span class="line"><span>   gender: Int,</span></span>
<span class="line"><span>   friendCount: Int,</span></span>
<span class="line"><span>   feedCount: Int,</span></span>
<span class="line"><span>   likeCount: Long,</span></span>
<span class="line"><span>   commentCount: Int</span></span>
<span class="line"><span>) {</span></span>
<span class="line"><span>   //..</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这是一个包含了很多参数的函数，在 Kotlin 当中，针对参数较多的函数，我们一般会以纵向的方式排列，这样的代码更符合我们从上到下的阅读习惯，省去从左往右翻的麻烦。</p><p>但是，如果我们像 Java 那样调用 createUser，代码就会非常难以阅读：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>createUser(&quot;Tom&quot;, 30, 1, 78, 2093, 10937, 3285)</span></span></code></pre></div><p>这里代码中的第一个参数，我们知道肯定是 name，但是到了后面那一堆的数字，就会让人迷惑了。这样的代码不仅难懂，同时还不好维护。</p><p>但如果我们这样写呢？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>createUser(</span></span>
<span class="line"><span>   name = &quot;Tom&quot;,</span></span>
<span class="line"><span>   age = 30,</span></span>
<span class="line"><span>   gender = 1,</span></span>
<span class="line"><span>   friendCount = 78,</span></span>
<span class="line"><span>   feedCount = 2093,</span></span>
<span class="line"><span>   likeCount = 10937,</span></span>
<span class="line"><span>   commentCount = 3285</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>可以看到，在这段代码中，我们把函数的形参加了进来，形参和实参用“=”连接，建立了两者的对应关系。对比前面 Java 风格的写法，这样的代码可读性更强了。如果将来你想修改likeCount 这个参数，也可以轻松做到。这其实就体现出了 Kotlin 命名参数的可读性与易维护性两个优势。</p><p>而除了命名参数这个特性，Kotlin 还支持参数默认值，这个特性在参数较多的情况下同样有很大的优势：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fun createUser(</span></span>
<span class="line"><span>   name: String,</span></span>
<span class="line"><span>   age: Int,</span></span>
<span class="line"><span>   gender: Int = 1,</span></span>
<span class="line"><span>   friendCount: Int = 0,</span></span>
<span class="line"><span>   feedCount: Int = 0,</span></span>
<span class="line"><span>   likeCount: Long = 0L,</span></span>
<span class="line"><span>   commentCount: Int = 0</span></span>
<span class="line"><span>) {</span></span>
<span class="line"><span>   //..</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>我们可以看到，gender、friendCount、feedCount、likeCount、commentCount 这几个参数都被赋予了默认值。这样做的好处就在于，我们在调用的时候可以省很多事情。比如说，下面这段代码就只需要传 3 个参数，剩余的 4 个参数没有传，但是 Kotlin 编译器会自动帮我们填上默认值。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>createUser(</span></span>
<span class="line"><span>   name = &quot;Tom&quot;,</span></span>
<span class="line"><span>   age = 30,</span></span>
<span class="line"><span>   commentCount = 3285</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>对于无默认值的参数，编译器会强制要求我们在调用处传参；对于有默认值的参数，则可传可不传。Kotlin 这样的特性，在一些场景下就可以极大地提升我们的开发效率。</p><p>而如果是在 Java 当中要实现类似的事情，我们就必须手动定义“3 个参数的 createUser 函数”，或者是使用 Builder 设计模式。</p><h2 id="流程控制" tabindex="-1">流程控制 <a class="header-anchor" href="#流程控制" aria-label="Permalink to &quot;流程控制&quot;">​</a></h2><p>在 Kotlin 当中，流程控制主要有 if、when、for、 while，这些语句可以控制代码的执行流程。它们也是体现代码逻辑的关键。下面我们就来一一学习下。</p><h3 id="if" tabindex="-1">if <a class="header-anchor" href="#if" aria-label="Permalink to &quot;if&quot;">​</a></h3><p>if 语句，在程序当中主要是用于逻辑判断。Kotlin 当中的 if 与 Java 当中的基本一致：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val i = 1</span></span>
<span class="line"><span>if (i &gt; 0) {</span></span>
<span class="line"><span>   print(&quot;Big&quot;)</span></span>
<span class="line"><span>} else {</span></span>
<span class="line"><span>   print(&quot;Small&quot;)</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>输出结果：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Big</span></span></code></pre></div><p>可以看到，由于 i 大于 0，所以程序会输出“Big”，这很好理解。不过 Kotlin 的 if，并不是程序语句（Statement）那么简单，它还可以作为表达式（Expression）来使用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val i = 1</span></span>
<span class="line"><span>val message = if (i &gt; 0) &quot;Big&quot; else &quot;Small&quot;</span></span>
<span class="line"><span>print(message)</span></span></code></pre></div><ul><li>输出结果：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Big</span></span></code></pre></div><p>以上的代码其实跟之前的代码差不多，它们做的是同一件事。不同的是，我们把 if 当作表达式在用，将 if 判断的结果，赋值给了一个变量。同时，Kotlin 编译会根据 if 表达式的结果自动推导出变量“message”的类型为“String”。这种方式就使得 Kotlin 的代码更加简洁。</p><p>而类似的逻辑，如果要用 Java 来实现的话，我们就必须先在 if 外面定义一个变量 message，然后分别在两个分支内对 message 赋值：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int i = 1</span></span>
<span class="line"><span>String message = &quot;&quot;</span></span>
<span class="line"><span>if (i &gt; 0) {</span></span>
<span class="line"><span>   message = &quot;Big&quot;</span></span>
<span class="line"><span>} else {</span></span>
<span class="line"><span>   message = &quot;Small&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>print(message)</span></span></code></pre></div><p>这样两相对比下，我们会发现 Java 的实现方式明显丑陋一些：不仅代码行数更多，逻辑也松散了。</p><p>另外，由于 Kotlin 当中明确规定了类型分为“可空类型”“不可空类型”，因此，我们会经常遇到可空的变量，并且要判断它们是否为空。我们直接来看个例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fun getLength(text: String?): Int {</span></span>
<span class="line"><span> return if (text != null) text.length else 0</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这个例子当中，我们把 if 当作表达式，如果 text 不为空，我们就算出它的长度；如果它为空，长度就取 0。</p><p>但是，如果你实际使用 Kotlin 写过代码，你会发现：在 Kotlin 中，类似这样的判断逻辑出现得非常频繁，如果每次都要写一个完整的 if else 分支，其实也很麻烦。</p><p>为此，Kotlin 针对这种情况就提供了一种简写，叫做 Elvis 表达式。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fun getLength(text: String?): Int {</span></span>
<span class="line"><span> return text?.length ?: 0</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>可以看到，通过 Elvis 表达式，我们就再也不必写“if (xxx != null) xxx else xxx”这</span></span></code></pre></div><p>样的赋值代码了。它在提高代码可读性的同时，还能提高我们的编码效率。</p><h3 id="when" tabindex="-1">when <a class="header-anchor" href="#when" aria-label="Permalink to &quot;when&quot;">​</a></h3><p>when 语句，在程序当中主要也是用于逻辑判断的。当我们的代码逻辑只有两个分支的时候，我们一般会使用 if/else，而在大于两个逻辑分支的情况下，我们使用 when。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val i: Int = 1</span></span>
<span class="line"><span>when(i) {</span></span>
<span class="line"><span>   1 -&gt; print(&quot;一&quot;)</span></span>
<span class="line"><span>   2 -&gt; print(&quot;二&quot;)</span></span>
<span class="line"><span>   else -&gt; print(&quot;i 不是一也不是二&quot;)</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>输出结果：一</li></ul><p>when 语句有点像 Java 里的 switch case 语句，不过 Kotlin 的 when 更加强大，它同时也可以作为表达式，为变量赋值，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val i: Int = 1</span></span>
<span class="line"><span>val message = when(i) {</span></span>
<span class="line"><span>   1 -&gt; &quot;一&quot;</span></span>
<span class="line"><span>   2 -&gt; &quot;二&quot;</span></span>
<span class="line"><span>   else -&gt; &quot;i 不是一也不是二&quot; // 如果去掉这行，会报错</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>print(message)</span></span></code></pre></div><p>另外，与 switch 不一样的是，when 表达式要求它里面的逻辑分支必须是完整的。举个例子，以上的代码，如果去掉 else 分支，编译器将报错，原因是：i 的值不仅仅只有 1 和 2，这两个分支并没有覆盖所有的情况，所以会报错。</p><h3 id="循环迭代-while-与-for" tabindex="-1">循环迭代：while 与 for <a class="header-anchor" href="#循环迭代-while-与-for" aria-label="Permalink to &quot;循环迭代：while 与 for&quot;">​</a></h3><p>首先 while 循环，我们一般是用于重复执行某些代码，它在使用上和 Java 也没有什么区别：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   println</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(i)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   i</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">++</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> j </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   println</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(j)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   j</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">++</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (j </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><ul><li>输出结果：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>0</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>2</span></span></code></pre></div><p>但是对于 for 语句，Kotlin 和 Java 的用法就明显不一样了。</p><p>在 Java 当中，for 也会经常被用于循环，经常被用来替代 while。不过，Kotlin 的 for 语句更多的是用于“迭代”。比如，以下代码就代表了迭代 array 这个数组里的所有元素，程序会依次打印出：“1、2、3”。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val array = arrayOf(1, 2, 3)</span></span>
<span class="line"><span>for (i in array) {</span></span>
<span class="line"><span>   println(i)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>而除了迭代数组和集合以外，Kotlin 还支持迭代一个“区间”。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>首先，要定义一个区间，我们可以使用“..”来连接数值区间的两端，比如“1..3”就代表从 1</span></span></code></pre></div><p>到 3 的闭区间，左闭右闭：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>val oneToThree = 1..3 // 代表 [1, 3]</span></span></code></pre></div><p>接着，我们就可以使用 for 语句，来对这个闭区间范围进行迭代：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for (i in oneToThree) {</span></span>
<span class="line"><span>   println(i)</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>输出结果：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>3</span></span></code></pre></div><p>甚至，我们还可以逆序迭代一个区间，比如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for (i in 6 downTo 0 step 2) {</span></span>
<span class="line"><span>   println(i)</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>输出结果：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>6</span></span>
<span class="line"><span>4</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>0</span></span></code></pre></div><p>以上代码的含义就是逆序迭代一个区间，从 6 到 0，每次迭代的步长是 2，这意味着 6 迭代过</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>后，到 4、2，最后到 0。需要特别注意的是，逆序区间我们不能使用“6..0”来定义，如果用</span></span></code></pre></div><p>这样的方式来定义的话，代码将无法正常运行。</p><p>好了，那么到目前为止，Kotlin 的变量、基础类型、函数、流程控制，我们就都已经介绍完了。掌握好这些知识点，我们就已经可以写出简单的程序了。当然，我们的 Kotlin 学习之路才刚刚开始，在下节课，我会带你来学习 Kotlin 面向对象相关的知识点。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>学完了这节课，现在我们知道虽然 Kotlin 和 Java 的语法很像，但在一些细节之处，Kotlin 总会有一些新的东西。如果你仔细琢磨这些不同点，你会发现它正是大部分程序员所需要的。举个例子，作为开发者，我们都讨厌写冗余的代码，喜欢简洁易懂的代码。那么在今天学完了基础语法之后，我们可以来看看 Kotlin 在这方面都做了哪些改进：</p><ul><li><p>支持类型推导；</p></li><li><p>代码末尾不需要分号；</p></li><li><p>字符串模板；</p></li><li><p>原始字符串，支持复杂文本格式；</p></li><li><p>单一表达式函数，简洁且符合直觉；</p></li><li><p>函数参数支持默认值，替代 Builder 模式的同时，可读性还很强；</p></li><li><p>if 和 when 可以作为表达式。</p></li></ul><p>同时，JetBrains 也非常清楚开发者在什么情况下容易出错，所以，它在语言层面也做了很多改进：</p><ul><li><p>强制区分“可为空变量类型”和“不可为空变量类型”，规避空指针异常；</p></li><li><p>推崇不可变性（val），对于没有修改需求的变量，IDE 会智能提示开发者将“var”改为“val”；</p></li><li><p>基础类型不支持隐式类型转换，这能避免很多隐藏的问题；</p></li><li><p>数组访问行为与集合统一，不会出现 array.length、list.size 这种恼人的情况；</p></li><li><p>函数调用支持命名参数，提高可读性，在后续维护代码的时候不易出错；</p></li><li><p>when 表达式，强制要求逻辑分支完整，让你写出来的逻辑永远不会有漏洞。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9C%B1%E6%B6%9B%C2%B7Kotlin%E7%BC%96%E7%A8%8B%E7%AC%AC%E4%B8%80%E8%AF%BE/images/01-Kotlin%25E5%259F%25BA%25E7%25A1%2580%25E8%25AF%25AD%25E6%25B3%2595/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9C%B1%E6%B6%9B%C2%B7Kotlin%E7%BC%96%E7%A8%8B%E7%AC%AC%E4%B8%80%E8%AF%BE/images/01-Kotlin%25E5%259F%25BA%25E7%25A1%2580%25E8%25AF%25AD%25E6%25B3%2595/3.png" alt=""></a></p><p>这些都是 Kotlin 的闪光点，也是它最珍贵的地方。</p><p>这一切，都得益于 Kotlin 的发明者 JetBrains。作为最负盛名的 IDE 创造者，JetBrains 能深刻捕捉到开发者的需求。它知道开发者喜欢什么、讨厌什么，它甚至知道开发者容易犯什么样的错误，从而在语言设计的层面规避错误。站在这个角度看，JetBrains 能够创造出炙手可热的Kotlin 语言，就一点都不奇怪了。</p><p>以上这么多的“闪光点”还仅仅只是局限于我们这节课的内容，如果放眼全局，这样的例子更是数不胜数。Kotlin 对比 Java 的提升，如果独立去看其中的某一个点，都不足以让一个开发者心动。不过，一旦这样的改善积少成多，Kotlin 的优势就会显得尤为明显。这也是很多程序员表示“Kotlin 用过了就回不去”的原因。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>虽然 Kotlin 在语法层面摒弃了“原始类型”，但有时候为了性能考虑，我们确实需要用“原始类型”。这时候我们应该怎么办？</p><p>欢迎在评论区分享你的思路，这个问题我会在第三节课给出答案，我们下节课再见。</p>`,193)])])}const k=a(l,[["render",e]]);export{g as __pageData,k as default};
